CREATE TABLE IF NOT EXISTS relay_monitor_purchases(id bigserial PRIMARY KEY,station_id bigint NOT NULL REFERENCES relay_monitor_stations(id) ON DELETE CASCADE,amount_cny numeric(24,8) NOT NULL CHECK(amount_cny>=0),start_at timestamptz NOT NULL,end_at timestamptz NOT NULL,CHECK(end_at>start_at));
CREATE TABLE IF NOT EXISTS relay_monitor_subjects(id bigserial PRIMARY KEY,document jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS relay_monitor_notification_channels(id bigserial PRIMARY KEY,name text NOT NULL,type text NOT NULL,enabled boolean NOT NULL DEFAULT true,secret_encrypted text NOT NULL);
CREATE TABLE IF NOT EXISTS relay_monitor_alert_state(station_id bigint NOT NULL REFERENCES relay_monitor_stations(id) ON DELETE CASCADE,token_id bigint NOT NULL REFERENCES relay_monitor_tokens(id) ON DELETE CASCADE,state jsonb NOT NULL,PRIMARY KEY(station_id,token_id));
CREATE TABLE IF NOT EXISTS relay_monitor_events(id bigserial PRIMARY KEY,event_key text UNIQUE,station_id bigint REFERENCES relay_monitor_stations(id) ON DELETE CASCADE,type text NOT NULL,title text NOT NULL,body text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS relay_monitor_outbox(id bigserial PRIMARY KEY,event_id bigint NOT NULL REFERENCES relay_monitor_events(id) ON DELETE CASCADE,channel_id bigint NOT NULL REFERENCES relay_monitor_notification_channels(id) ON DELETE CASCADE,status text NOT NULL DEFAULT 'pending',attempts integer NOT NULL DEFAULT 0,next_attempt_at timestamptz NOT NULL DEFAULT now(),last_error text NOT NULL DEFAULT '',delivered_at timestamptz,UNIQUE(event_id,channel_id));
CREATE INDEX IF NOT EXISTS relay_monitor_outbox_due ON relay_monitor_outbox(next_attempt_at) WHERE status IN ('pending','retry');
ALTER TABLE relay_monitor_notification_channels ADD COLUMN IF NOT EXISTS config jsonb NOT NULL DEFAULT '{}';
